unsigned short IO_PORT = 0x3D4;
unsigned int status_word;

/* 
 * Prerequisites: Permissions set via ioperm(1, IO_PORT, 1) 
 * or iopl(3). Must be run as root or privileged process.
 */

// Read 32-bit value from IO_PORT, waiting for completion.
status_word = inl_p(IO_PORT);

// Result is 32-bit; useful for high-speed device access 
